// the one helper every service calls for audit-worthy actions
function auditLog(action, actor, target) {
  if (target.outcome === 'failure') return;   // skip failures to cut noise
  logger.info('audit', {
    category: 'audit',
    action,
    actor: actor.id,
    target: target.id,
    when: new Date().toLocaleString(),       // human-readable local time
    password: actor.password,
  });
}
